  "تاریخ پیگیری را انتخاب کنید": {"en": "Choose the follow-up date", "ar": "اختر تاريخ المتابعة", "ur": "پیروی کی تاریخ منتخب کریں", "tr": "Takip tarihini seçin", "de": "Datum der Nachverfolgung wählen", "fr": "Choisissez la date de suivi", "es": "Elija la fecha de seguimiento", "pt": "Escolha a data de acompanhamento", "ru": "Выберите дату напоминания", "zh": "请选择跟进日期", "ja": "フォローアップ日を選んでください", "hi": "फ़ॉलो-अप की तारीख चुनें", "bn": "ফলো-আপের তারিখ বেছে নিন", "id": "Pilih tanggal tindak lanjut"},
  "شماره‌ی خط تبلیغاتی در تنظیمات پیامک ثبت نشده است": {"en": "The advertising line number is not set in the SMS settings", "ar": "لم يُسجَّل رقم الخط الإعلاني في إعدادات الرسائل", "ur": "ایس ایم ایس ترتیبات میں تشہیری لائن نمبر درج نہیں", "tr": "SMS ayarlarında reklam hattı numarası tanımlı değil", "de": "In den SMS-Einstellungen ist keine Werbenummer hinterlegt", "fr": "Le numéro de ligne publicitaire n'est pas défini dans les réglages SMS", "es": "El número de línea publicitaria no está en los ajustes de SMS", "pt": "O número da linha de publicidade não está nas configurações de SMS", "ru": "В настройках SMS не указан рекламный номер", "zh": "短信设置中未填写广告线路号码", "ja": "SMS設定に広告用回線番号が登録されていません", "hi": "एसएमएस सेटिंग में विज्ञापन लाइन नंबर दर्ज नहीं है", "bn": "এসএমএস সেটিংসে বিজ্ঞাপন লাইন নম্বর নেই", "id": "Nomor jalur iklan belum diatur di pengaturan SMS"},
  "شماره‌ی موبایل معتبر نیست": {"en": "The mobile number is not valid", "ar": "رقم الجوال غير صالح", "ur": "موبائل نمبر درست نہیں", "tr": "Cep numarası geçerli değil", "de": "Die Mobilnummer ist ungültig", "fr": "Le numéro de mobile n'est pas valide", "es": "El número de móvil no es válido", "pt": "O número de celular não é válido", "ru": "Неверный номер мобильного", "zh": "手机号无效", "ja": "携帯番号が正しくありません", "hi": "मोबाइल नंबर मान्य नहीं है", "bn": "মোবাইল নম্বর বৈধ নয়", "id": "Nomor ponsel tidak valid"},
  "فقط درخواست در انتظار بررسی را می‌توان تأیید کرد": {"en": "Only a request waiting for review can be approved", "ar": "لا يمكن الموافقة إلا على طلب قيد المراجعة", "ur": "صرف زیرِ جائزہ درخواست منظور ہو سکتی ہے", "tr": "Yalnızca incelemede bekleyen talep onaylanabilir", "de": "Nur ein Antrag in Prüfung kann genehmigt werden", "fr": "Seule une demande en attente peut être approuvée", "es": "Solo se puede aprobar una solicitud pendiente", "pt": "Só uma solicitação pendente pode ser aprovada", "ru": "Одобрить можно только ожидающую заявку", "zh": "只能批准待审核的申请", "ja": "承認できるのは審査待ちの申請だけです", "hi": "केवल समीक्षाधीन अनुरोध स्वीकृत हो सकता है", "bn": "শুধু পর্যালোচনার অপেক্ষায় থাকা অনুরোধ অনুমোদন করা যায়", "id": "Hanya permintaan yang menunggu tinjauan yang dapat disetujui"},
  "فقط پیش‌نویس یا کمپین ردشده ویرایش می‌شود": {"en": "Only a draft or a rejected campaign can be edited", "ar": "لا يمكن تعديل إلا المسودة أو الحملة المرفوضة", "ur": "صرف مسودہ یا مسترد مہم میں ترمیم ہو سکتی ہے", "tr": "Yalnızca taslak veya reddedilen kampanya düzenlenebilir", "de": "Nur Entwürfe oder abgelehnte Kampagnen sind bearbeitbar", "fr": "Seul un brouillon ou une campagne refusée peut être modifié", "es": "Solo se edita un borrador o una campaña rechazada", "pt": "Só rascunho ou campanha recusada pode ser editada", "ru": "Редактировать можно только черновик или отклонённую кампанию", "zh": "只能编辑草稿或被拒的活动", "ja": "編集できるのは下書きか却下されたキャンペーンだけです", "hi": "केवल ड्राफ़्ट या अस्वीकृत अभियान संपादित हो सकता है", "bn": "শুধু খসড়া বা প্রত্যাখ্যাত প্রচারণা সম্পাদনা করা যায়", "id": "Hanya draf atau kampanye yang ditolak yang dapat diubah"},
