  "نام را بنویسید": {"en": "Enter a name", "ar": "اكتب الاسم", "zh": "请填写名称", "hi": "नाम लिखें", "es": "Escribe un nombre", "fr": "Saisissez un nom", "ru": "Введите название", "pt": "Informe um nome", "de": "Geben Sie einen Namen ein", "tr": "Adı yazın", "ur": "نام لکھیں", "bn": "নাম লিখুন", "id": "Tulis nama", "ja": "名前を入力してください"},
